import json, re, random, chess, sys, time
R = json.load(open("/tmp/obench-cell-puhex3l_/bench_opencode_regex-chess_szcik2jm/re.json"))
def run(fen):
    for p, r in R: fen = re.sub(p, r, fen)
    return fen.split("\n")
def expected(fen):
    b = chess.Board(fen); s = set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN: continue
        c = b.copy(); c.push(m); s.add(" ".join(c.fen().split(" ")[:-2]))
    return s
def check(fen):
    ours = [" ".join(x.split(" ")[:-2]) for x in run(fen)]
    exp = expected(fen)
    ok = len(ours) == len(exp) and all(x in exp or x.rpartition(" ")[0]+" -" in exp for x in ours)
    if not ok:
        print("FAIL", fen); print(sorted(ours)); print(sorted(exp)); sys.exit(1)
print(run("<REDACTED_B64> w kq - 0 1"))
random.seed(1); n = 0; t = time.time()
for g in range(400):
    b = chess.Board()
    while not b.is_game_over() and b.ply() < 300:
        if b.turn == chess.WHITE:
            check(b.fen()); n += 1
        moves = list(b.legal_moves)
        caps = [m for m in moves if b.is_capture(m) or m.promotion or b.is_castling(m)]
        b.push(random.choice(caps if caps and random.random() < 0.5 else moves))
print("ok", n, time.time() - t)
